//go:build integration

package integration

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/strategy"
	"entire.io/cli/cmd/entire/cli/trailers"
	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// TestManualCommit_Attribution tests the full attribution calculation flow:
// 1. Agent creates checkpoint 1
// 2. User makes changes (some staged, some not)
// 3. User enters new prompt (attribution calculated at prompt start)
// 4. Agent creates checkpoint 2
// 5. User commits (condensation happens)
// 6. Verify attribution metadata is correct
func TestManualCommit_Attribution(t *testing.T) {
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	// Create initial commit
	env.WriteFile("main.go", "package main\n")
	env.GitAdd("main.go")
	env.GitCommit("Initial commit")

	env.InitEntire(strategy.StrategyNameManualCommit)

	initialHead := env.GetHeadHash()
	t.Logf("Initial HEAD: %s", initialHead[:7])

	// ========================================
	// CHECKPOINT 1: Agent adds function
	// ========================================
	t.Log("Creating checkpoint 1 (agent adds function)")

	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (prompt 1) failed: %v", err)
	}

	// Agent adds 4 lines
	checkpoint1Content := "package main\n\nfunc agentFunc() {\n\treturn 42\n}\n"
	env.WriteFile("main.go", checkpoint1Content)

	session.CreateTranscript(
		"Add agent function",
		[]FileChange{{Path: "main.go", Content: checkpoint1Content}},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (checkpoint 1) failed: %v", err)
	}

	// ========================================
	// USER EDITS: Partial staging scenario
	// ========================================
	t.Log("User makes edits with partial staging")

	// User adds 10 lines to worktree
	userContentFull := checkpoint1Content +
		"// User comment 1\n" +
		"// User comment 2\n" +
		"// User comment 3\n" +
		"// User comment 4\n" +
		"// User comment 5\n" +
		"// User comment 6\n" +
		"// User comment 7\n" +
		"// User comment 8\n" +
		"// User comment 9\n" +
		"// User comment 10\n"
	env.WriteFile("main.go", userContentFull)

	// User stages only first 5 lines of changes
	// To simulate partial staging, we'll write the partial content to a temp file
	// and use git hash-object + update-index to stage it
	userContentPartial := checkpoint1Content +
		"// User comment 1\n" +
		"// User comment 2\n" +
		"// User comment 3\n" +
		"// User comment 4\n" +
		"// User comment 5\n"

	// Stage the partial content using git plumbing
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}

	// Write partial content as a blob
	blobHash, err := repo.Storer.SetEncodedObject(
		plumbing.NewBlobFromBytes([]byte(userContentPartial)),
	)
	if err != nil {
		t.Fatalf("failed to create blob: %v", err)
	}

	// Update index with the partial content
	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}

	idx, err := worktree.Filesystem.Root()
	if err != nil {
		t.Fatalf("failed to get filesystem root: %v", err)
	}

	// Use git CLI to update index (easier than go-git plumbing)
	env.RunGitCommand("update-index", "--add", "--cacheinfo", "100644", blobHash.String(), "main.go")

	// ========================================
	// CHECKPOINT 2: New prompt (attribution calculated)
	// ========================================
	t.Log("User enters new prompt (attribution should capture 5 staged lines)")

	// Simulate UserPromptSubmit hook - this calculates attribution at prompt start
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (prompt 2) failed: %v", err)
	}

	// Agent adds more lines
	checkpoint2Content := userContentFull + "\nfunc agentFunc2() {\n\treturn 100\n}\n"
	env.WriteFile("main.go", checkpoint2Content)

	session.CreateTranscript(
		"Add second agent function",
		[]FileChange{{Path: "main.go", Content: checkpoint2Content}},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (checkpoint 2) failed: %v", err)
	}

	// Verify 2 rewind points
	points := env.GetRewindPoints()
	if len(points) != 2 {
		t.Fatalf("Expected 2 rewind points, got %d", len(points))
	}

	// ========================================
	// USER COMMITS: Condensation happens
	// ========================================
	t.Log("User commits (condensation should happen)")

	// Stage all changes and commit
	env.GitAdd("main.go")
	commitHash := env.GitCommit("Add functions")
	t.Logf("User commit: %s", commitHash[:7])

	// Get checkpoint ID from commit message
	commitObj := env.GetCommit(commitHash)
	checkpointID, found := trailers.ParseCheckpoint(commitObj.Message)
	if !found {
		t.Fatal("Commit should have Entire-Checkpoint trailer")
	}
	t.Logf("Checkpoint ID: %s", checkpointID)

	// ========================================
	// VERIFY ATTRIBUTION
	// ========================================
	t.Log("Verifying attribution in metadata")

	// Read metadata from entire/sessions branch
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName("entire/sessions"), true)
	if err != nil {
		t.Fatalf("Failed to get entire/sessions branch: %v", err)
	}

	sessionsCommit, err := repo.CommitObject(sessionsRef.Hash())
	if err != nil {
		t.Fatalf("Failed to get sessions commit: %v", err)
	}

	sessionsTree, err := sessionsCommit.Tree()
	if err != nil {
		t.Fatalf("Failed to get sessions tree: %v", err)
	}

	// Read metadata.json from sharded path
	metadataPath := checkpointID.String()[:2] + "/" + checkpointID.String()[2:] + "/metadata.json"
	metadataFile, err := sessionsTree.File(metadataPath)
	if err != nil {
		t.Fatalf("Failed to read metadata.json: %v", err)
	}

	metadataContent, err := metadataFile.Contents()
	if err != nil {
		t.Fatalf("Failed to read metadata content: %v", err)
	}

	var metadata checkpoint.Checkpoint
	if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {
		t.Fatalf("Failed to parse metadata.json: %v", err)
	}

	// Verify InitialAttribution exists
	if metadata.InitialAttribution == nil {
		t.Fatal("InitialAttribution is nil")
	}

	attr := metadata.InitialAttribution
	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, human_removed=%d, total=%d, percentage=%.1f%%",
		attr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.HumanRemoved,
		attr.TotalCommitted, attr.AgentPercentage)

	// Verify attribution values
	// Agent added:
	//   - checkpoint 1: 4 lines (func agentFunc)
	//   - checkpoint 2: 4 lines (func agentFunc2)
	//   Total: 8 agent lines
	if attr.AgentLines != 8 {
		t.Errorf("AgentLines = %d, want 8 (4 from checkpoint 1 + 4 from checkpoint 2)",
			attr.AgentLines)
	}

	// User added:
	//   - Between checkpoints: 5 lines (staged comments, captured in PromptAttribution)
	//   - After checkpoint 2: 5 lines (remaining unstaged comments, captured in shadow→head diff)
	//   Total: 10 user lines
	// Note: This assumes the final commit includes all 10 user comments
	if attr.HumanAdded != 10 {
		t.Errorf("HumanAdded = %d, want 10 (5 staged between checkpoints + 5 after checkpoint 2)",
			attr.HumanAdded)
	}

	// Total committed = agent + user = 8 + 10 = 18
	if attr.TotalCommitted != 18 {
		t.Errorf("TotalCommitted = %d, want 18 (8 agent + 10 user)",
			attr.TotalCommitted)
	}

	// Agent percentage = 8 / 18 * 100 = 44.4%
	expectedPercentage := 44.4
	if attr.AgentPercentage < expectedPercentage-0.5 || attr.AgentPercentage > expectedPercentage+0.5 {
		t.Errorf("AgentPercentage = %.1f%%, want ~%.1f%%",
			attr.AgentPercentage, expectedPercentage)
	}
}

// TestManualCommit_AttributionDeletionOnly tests attribution for deletion-only commits
func TestManualCommit_AttributionDeletionOnly(t *testing.T) {
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	// Create initial commit with content
	initialContent := "package main\n\nfunc oldFunc1() {}\nfunc oldFunc2() {}\nfunc oldFunc3() {}\n"
